import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1795170900000}'),i={name:"ja/guide/faq.md"};function l(n,a,s,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><p>Persim についての簡単な回答。</p><h3 id="無料ですか" tabindex="-1">無料ですか？ <a class="header-anchor" href="#無料ですか" aria-label="Permalink to &quot;無料ですか？&quot;">​</a></h3><p>基本機能は無料で使えます。一部の高度な機能はアプリ内課金で利用でき、無料版ではタブバーに小さなバッジが表示されます。</p><h3 id="対応-os-は" tabindex="-1">対応 OS は？ <a class="header-anchor" href="#対応-os-は" aria-label="Permalink to &quot;対応 OS は？&quot;">​</a></h3><p>macOS 12 以降、Apple Silicon と Intel の Mac に対応しています。</p><h3 id="データはアップロードされますか" tabindex="-1">データはアップロードされますか？ <a class="header-anchor" href="#データはアップロードされますか" aria-label="Permalink to &quot;データはアップロードされますか？&quot;">​</a></h3><p>アカウントは不要で、履歴、ブックマーク、セッション、ダウンロードは Mac 内に残ります。通信が必要な機能（広告ブロックの購読更新など）だけがインターネットに接続します。</p><h3 id="ブックマークを移行するには" tabindex="-1">ブックマークを移行するには？ <a class="header-anchor" href="#ブックマークを移行するには" aria-label="Permalink to &quot;ブックマークを移行するには？&quot;">​</a></h3><p>Chrome や Edge で HTML に書き出し、Persim のブックマークマネージャーで読み込みます。フォルダーや重複リンクは自動で処理されます。</p><h3 id="動画を保存するには" tabindex="-1">動画を保存するには？ <a class="header-anchor" href="#動画を保存するには" aria-label="Permalink to &quot;動画を保存するには？&quot;">​</a></h3><p>メディアパネルで検出された動画を選んでダウンロードします。分割された動画はひとつの MP4 にまとまります。</p><h3 id="言語を変えるには" tabindex="-1">言語を変えるには？ <a class="header-anchor" href="#言語を変えるには" aria-label="Permalink to &quot;言語を変えるには？&quot;">​</a></h3><p><code>persim://settings</code> → 「一般」→「言語」へ。25 言語から選べ、ウィンドウを開き直すと反映されます。</p><h3 id="その他の質問" tabindex="-1">その他の質問 <a class="header-anchor" href="#その他の質問" aria-label="Permalink to &quot;その他の質問&quot;">​</a></h3><p><strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> までご連絡ください。</p>',16)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
